using System;using System.IO;using System.Linq;using System.Reflection;using System.Collections.Generic;using UnityEditor;using UnityEngine;
public static class Draw01MiddleNormalFrameProbe{
[Serializable]public class Sample{public int a,b;public float[] weights,uv,sourceT,targetT;public float sourceHand,targetHand;}
[Serializable]public class Input{public Sample[] rows;}
[Serializable]public class OutputRow{public int sample,mip;public Vector4 packed;}
[Serializable]public class Output{public string scope="Actual original normal Texture SampleLevel at unchanged native sampler; raw PBR basis diagnostic, not VT rendering or filter equivalence.";public OutputRow[] rows;}
public static void Run(){try{string Arg(string k)=>Draw01AppearancePartitionCheck.Argument(k);var manifest=JsonUtility.FromJson<PrepareRepeatUnits.Manifest>(File.ReadAllText(Arg("-unitManifest")));var channel=manifest.units[0].channels.Single(c=>c.name=="_NormalMap");var input=JsonUtility.FromJson<Input>(File.ReadAllText(Arg("-samples")));var codec=PreparePaint.OpenCodec(Arg("-gameData"));try{var bytes=File.ReadAllBytes(channel.path);if(PreparePaint.Digest(bytes)!=channel.sha256)throw new Exception("Source hash mismatch");int size=(int)typeof(PrepareRepeatUnits).GetMethod("NativeRawSize",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{bytes});using var stream=new MemoryStream(bytes);var tex=BridgeBuilder.Bridges.MovableTextureSource.Read(stream,b=>PreparePaint.DecodeRaw(b,size));try{var shader=AssetDatabase.LoadAssetAtPath<ComputeShader>("Assets/Editor/Draw01NormalProbe.compute");var queries=new List<Vector3>();foreach(int mip in new[]{0,3,6})foreach(var row in input.rows)queries.Add(new Vector3(row.uv[0],row.uv[1],mip));using var buffer=new ComputeBuffer(queries.Count,12);using var result=new ComputeBuffer(queries.Count,16);buffer.SetData(queries);shader.SetTexture(0,"_Source",tex);shader.SetBuffer(0,"_Queries",buffer);shader.SetBuffer(0,"_Result",result);shader.SetInt("_Count",queries.Count);shader.Dispatch(0,(queries.Count+31)/32,1,1);var colors=new Vector4[queries.Count];result.GetData(colors);var rows=new List<OutputRow>();for(int i=0;i<colors.Length;i++)rows.Add(new OutputRow{sample=i%input.rows.Length,mip=(int)queries[i].z,packed=colors[i]});File.WriteAllText(Arg("-report"),JsonUtility.ToJson(new Output{rows=rows.ToArray()},true));}finally{UnityEngine.Object.DestroyImmediate(tex);}}finally{PreparePaint.CloseCodec(codec);}EditorApplication.Exit(0);}catch(Exception e){Debug.LogException(e);EditorApplication.Exit(1);}}
}
